mapper.select:
SELECT  primary_key as quotationCode ,type , quotation_name, quotation_number,
buyer, seller, enterprise_code as ownedEnterpriseCode,customer_code,customer_contact as customerContactCode,
user_code as userCode, language, payment_strategy, column_titles,
amount_title, product_detail,clauses_chs,clauses_en,quotation_time, state,
data_version,
sell_quotation,sign_areas,delete_flag
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND primary_key = #{quotationCode}
AND user_code = #{userCode}

SELECT  primary_key as quotationCode ,type , quotation_name, quotation_number,
buyer, seller, enterprise_code as ownedEnterpriseCode,customer_code,customer_contact as customerContactCode,
user_code as userCode, language, payment_strategy, column_titles,
amount_title, product_detail,clauses_chs,clauses_en,quotation_time, state,
data_version,
sell_quotation,sign_areas,delete_flag
FROM  ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND user_code = #{userCode}
AND delete_flag= 'f'

    AND quotation_number LIKE '%'|| #{quotationNumber} ||'%'


    AND state = #{state}


    AND quotation_time >= #{quotationTimePreDate}


    AND quotation_time <= #{quotationTimePostDate}

ORDER BY create_time DESC

mapper.delete:
DELETE FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND primary_key = #{quotationCode}
  AND data_version = #{clientDataVersion}

mapper.update:
UPDATE ${tableName}
SET state = #{model.state}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.quotationCode}
  AND data_version = #{clientDataVersion}
